WITH customer_returns AS ( SELECT cr.cr_returning_customer_sk AS customer_sk, SUM(cr.cr_net_loss) AS total_net_loss, COUNT(*) AS return_cnt, MAX(cr.cr_returned_date_sk) AS last_return_date_sk, MIN(cr.cr_returned_date_sk) AS first_return_date_sk FROM catalog_returns cr GROUP BY cr.cr_returning_customer_sk ), latest_return AS ( SELECT cr.cr_returning_customer_sk, cr.cr_returned_date_sk, cr.cr_catalog_page_sk, cr.cr_warehouse_sk, cr.cr_returning_addr_sk, ROW_NUMBER() OVER (PARTITION BY cr.cr_returning_customer_sk ORDER BY cr.cr_returned_date_sk DESC) AS rn FROM catalog_returns cr ) SELECT cr.customer_sk, cr.total_net_loss, cr.return_cnt, cr.last_return_date_sk, ca_ret.ca_city AS returning_city, ca_ret.ca_state AS returning_state, cp.cp_catalog_number, cp.cp_type, w.w_warehouse_name, CASE WHEN cr.total_net_loss > 50000 THEN 'BIG_SPENDER' ELSE 'REGULAR' END AS customer_segment, DENSE_RANK() OVER (ORDER BY cr.total_net_loss DESC) AS net_loss_customer_rank, cp.cp_catalog_page_number AS latest_catalog_page_number FROM customer_returns cr LEFT JOIN latest_return lr ON cr.customer_sk = lr.cr_returning_customer_sk AND lr.rn = 1 LEFT JOIN catalog_page cp ON lr.cr_catalog_page_sk = cp.cp_catalog_page_sk LEFT JOIN warehouse w ON lr.cr_warehouse_sk = w.w_warehouse_sk LEFT JOIN customer_address ca_ret ON lr.cr_returning_addr_sk = ca_ret.ca_address_sk ORDER BY net_loss_customer_rank LIMIT 15
